s = sys.stdin.read().split()[0]
n = len(s)
best = n
for i in range(n + 1):
    for j in range(i, n + 1):
        rest = s[:i] + s[j:]
        if len(set(rest)) == len(rest):
            best = min(best, j - i)
print(best)

